/**
 * Author-facing OpenTelemetry surface for {@link HostContext.otel}.
 *
 * Always present on `ctx.host`. Counters and histograms no-op when no meter
 * is running. `setAttributes` still tags open turn/tool spans when a
 * collector is attached. `forSession` is engine-only so a tool cannot
 * retarget another conversation's tags.
 */
import { deprecate } from "node:util";
import { attrs } from "./otel/attrs.js";
import { RESERVED_SPAN_ATTRIBUTES } from "./otel/reserved-attributes.js";
const METRIC_NAME = /^[A-Za-z][A-Za-z0-9_./-]*$/;
const RESERVED_METRICS = new Set([
    "cursor.token.usage",
    "cursor.tool.calls",
    "cursor.cost.usage",
    "agent_sdk.session.count",
    "agent_sdk.turn.count",
    "agent_sdk.subagent.count",
    "agent_sdk.http.duration",
]);
const warnHostOtelDeprecated = deprecate(() => { }, "[bdk:otel] deprecated: ctx.host.otel still runs for this release. Set OTEL_* variables and use metrics.getMeter or trace.getTracer from @opentelemetry/api.");
/** Build the host OpenTelemetry API for one agent process. */
export function createHostOtelApi(options) {
    return createBoundHostOtelApi({
        shared: {
            agentName: options.agentName,
            meter: options.meter ?? (() => undefined),
            boundMeter: undefined,
            collector: options.collector,
            instruments: new Map(),
            sessionTags: new Map(),
        },
        sessionId: options.sessionId,
        localTags: {},
    });
}
function createBoundHostOtelApi(state) {
    const api = {
        get enabled() {
            return state.shared.meter() !== undefined;
        },
        setAttributes(attributes) {
            warnHostOtelDeprecated();
            const cleaned = validateAttributes(attributes);
            if (state.sessionId === undefined) {
                Object.assign(state.localTags, cleaned);
                return;
            }
            mergeSessionTags(state, state.sessionId, cleaned);
            state.shared.collector?.setSessionAttributes(state.sessionId, cleaned);
        },
        increment(name, valueOrAttributes, maybeAttributes) {
            warnHostOtelDeprecated();
            const value = typeof valueOrAttributes === "number" ? valueOrAttributes : 1;
            const attributes = typeof valueOrAttributes === "number" ? maybeAttributes : valueOrAttributes;
            counter(state.shared, name)?.add(value, emitAttributes(state, attributes));
        },
        record(name, value, attributes) {
            warnHostOtelDeprecated();
            histogram(state.shared, name)?.record(value, emitAttributes(state, attributes));
        },
        forSession(sessionId) {
            const trimmed = sessionId.trim();
            if (trimmed === "") {
                throw new Error("host.otel.forSession requires a non-empty session id");
            }
            return createBoundHostOtelApi({
                shared: state.shared,
                sessionId: trimmed,
                localTags: {},
            });
        },
    };
    return api;
}
function mergeSessionTags(state, sessionId, incoming) {
    const bag = state.shared.sessionTags.get(sessionId) ?? {};
    Object.assign(bag, incoming);
    state.shared.sessionTags.set(sessionId, bag);
}
function emitAttributes(state, callSite) {
    return attrs({
        ...sessionBag(state),
        ...validateAttributes(callSite),
        "agent_sdk.agent": state.shared.agentName,
        ...(state.sessionId === undefined
            ? {}
            : {
                "cursor.conversation.id": state.sessionId,
                "agent_sdk.session_id": state.sessionId,
            }),
    });
}
function sessionBag(state) {
    if (state.sessionId === undefined) {
        return state.localTags;
    }
    const fromCollector = state.shared.collector?.getSessionAttributes(state.sessionId);
    const fromShared = state.shared.sessionTags.get(state.sessionId) ?? {};
    return {
        ...fromShared,
        ...(fromCollector ?? {}),
        ...state.localTags,
    };
}
function activeMeter(shared) {
    const meter = shared.meter();
    if (meter === undefined) {
        return undefined;
    }
    if (shared.boundMeter !== meter) {
        shared.boundMeter = meter;
        shared.instruments.clear();
    }
    return meter;
}
function counter(shared, name) {
    validateMetricName(name);
    const meter = activeMeter(shared);
    if (meter === undefined) {
        return undefined;
    }
    const existing = shared.instruments.get(name);
    if (existing !== undefined) {
        if (existing.kind !== "counter") {
            throw new Error(`host.otel metric "${name}" is already a histogram`);
        }
        return existing.instrument;
    }
    const instrument = meter.createCounter(name);
    shared.instruments.set(name, { kind: "counter", instrument });
    return instrument;
}
function histogram(shared, name) {
    validateMetricName(name);
    const meter = activeMeter(shared);
    if (meter === undefined) {
        return undefined;
    }
    const existing = shared.instruments.get(name);
    if (existing !== undefined) {
        if (existing.kind !== "histogram") {
            throw new Error(`host.otel metric "${name}" is already a counter`);
        }
        return existing.instrument;
    }
    const instrument = meter.createHistogram(name);
    shared.instruments.set(name, { kind: "histogram", instrument });
    return instrument;
}
function validateMetricName(name) {
    if (!METRIC_NAME.test(name)) {
        throw new Error(`host.otel metric name "${name}" must match [A-Za-z][A-Za-z0-9_./-]*`);
    }
    if (RESERVED_METRICS.has(name)) {
        throw new Error(`host.otel metric name "${name}" is reserved`);
    }
}
function validateAttributes(attributes) {
    if (attributes === undefined) {
        return {};
    }
    const out = {};
    for (const [key, value] of Object.entries(attributes)) {
        if (value === undefined) {
            continue;
        }
        if (RESERVED_SPAN_ATTRIBUTES.has(key)) {
            throw new Error(`host.otel attribute "${key}" is reserved; the runtime always sets it`);
        }
        if (typeof value !== "string" && typeof value !== "number" && typeof value !== "boolean") {
            throw new Error(`host.otel attribute "${key}" must be a string, number, or boolean`);
        }
        out[key] = value;
    }
    return out;
}
